import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/registers.sonIV7dm.svg",u=JSON.parse('{"title":"Registers","description":"","frontmatter":{},"headers":[],"relativePath":"REGISTERS.md","filePath":"REGISTERS.md"}'),d={name:"REGISTERS.md"};function n(i,e,h,c,l,g){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="registers" tabindex="-1">Registers <a class="header-anchor" href="#registers" aria-label="Permalink to &quot;Registers&quot;">​</a></h1><p>Registers are four numbers that the whole song shares. Pattern steps set them, add to them, use them to move notes and velocities, and compare them to decide whether a note plays. This page covers the Registers page; the pattern rows that work with registers are described under <a href="./PATTERNS#reg-mod-reg-apply-and-reg-cond">Reg. Mod, Reg. Apply and Reg. Cond</a> on the Patterns page.</p><p><img src="'+r+'" alt="The Registers page"></p><h2 id="register-settings" tabindex="-1">Register Settings <a class="header-anchor" href="#register-settings" aria-label="Permalink to &quot;Register Settings&quot;">​</a></h2><p>Press <code>R</code> on the main screen to open the Registers page, a grid with a row for each register and a column for each setting. The four registers, AX, BX, CX and DX, belong to the current song, and each has these settings, shown across the grid as Inc max, At limit, Minimum, Default, Maximum and Reset:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td>Default</td><td>0</td><td>The value the register holds when the song starts, and when a scene resets it.</td></tr><tr><td>Minimum</td><td>0</td><td>The lowest value the register can hold.</td></tr><tr><td>Maximum</td><td>10</td><td>The highest value the register can hold.</td></tr><tr><td>At limit</td><td>stop</td><td>What happens when a step adds past either end. &quot;stop&quot; stays at the end reached; &quot;reset&quot; goes back to Default; &quot;overflow&quot; lands on the other end; &quot;overflow right&quot; lands on Minimum when passing Maximum but stops at Minimum; &quot;overflow left&quot; does the reverse; and &quot;pick random&quot; lands anywhere from Minimum to Maximum, drawn from the song&#39;s seed.</td></tr><tr><td>Reset each scene</td><td>off</td><td>Whether the register goes back to Default as each scene first starts, though not on the scene&#39;s repeats. The Scene page&#39;s Reset field does the same for one scene.</td></tr><tr><td>Allowed inc max</td><td>20</td><td>The most a single step may add to the register or take from it; the <code>+=</code> rows stop there. Lowering it brings every add in every pattern the song plays within the new limit, and <code>Ctrl+Z</code> undoes that.</td></tr></tbody></table><p>Every number runs from -127 to 127, and Minimum can&#39;t be above Default, nor Default above Maximum; a change that would break that order is refused with the reason. The arrow keys move over the grid, stopping at every edge, and the line under it names the setting under the cursor in full. <code>[</code> and <code>]</code> change a number, <code>Enter</code> types one, and <code>Bksp</code> sets it back to its default. At limit steps through its choices with <code>[</code> and <code>]</code>, or <code>Enter</code> picks from a list, and <code>Space</code> or <code>Enter</code> turns Reset each scene on and off.</p><h2 id="overflow" tabindex="-1">Overflow <a class="header-anchor" href="#overflow" aria-label="Permalink to &quot;Overflow&quot;">​</a></h2><p>A register that overflows lands exactly on the other end, whatever amount was left over. With a range of 0 to 3, adding 1 to 3 gives 0, and so does adding 2; with At limit at &quot;stop&quot;, the register stays at 3. A file saved before At limit existed, with its old Wraps setting on, opens with At limit at &quot;overflow&quot;.</p><p><code>examples/learning/22_registers.yml</code> shows every register at work.</p>',10)])])}const p=t(d,[["render",n]]);export{u as __pageData,p as default};
